<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli')exit;
require dirname(__DIR__).'/src/AdminAuth.php';require dirname(__DIR__).'/src/Overview.php';
function overviewCheck(bool $ok,string $message):void{if(!$ok)throw new RuntimeException($message);}
$dsn=getenv('JINGO_TEST_DSN');if(!$dsn)exit(1);$opts=[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false];$user=getenv('JINGO_TEST_USER')?:'root';$password=getenv('JINGO_TEST_PASSWORD')?:'';$server=new PDO($dsn,$user,$password,$opts);$name='jingo_overview_test_'.bin2hex(random_bytes(6));$server->exec("CREATE DATABASE `$name` CHARACTER SET utf8mb4");$db=null;
try{
 $db=new PDO($dsn.';dbname='.$name,$user,$password,$opts);foreach(glob(dirname(__DIR__).'/database/*.sql') as $file)foreach(explode(';',file_get_contents($file)) as $sql)if(trim($sql)!=='')$db->exec($sql);$service=new Overview($db);$now=new DateTimeImmutable('2026-11-13T17:01:00Z');$empty=$service->get([],$now);overviewCheck($empty['date']==='2026-11-14'&&$empty['tomorrow']==='2026-11-15'&&$empty['total']===0&&$empty['pages']===1,'Empty/Vietnam dates');
 $insert=$db->prepare('INSERT INTO jingo_orders(id,code,request_id,request_hash,access_hash,snapshot,contact,booking_status,payment_status,instructions,created_at) VALUES (?,?,?,?,?,?,?,?,?,?,?)');$expected=['today'=>0,'tomorrow'=>0,'due'=>0,'unpaid'=>0,'requested'=>0,'created'=>0];
 for($i=1;$i<=34;$i++){$id='00000000-0000-4000-8000-'.str_pad((string)$i,12,'0',STR_PAD_LEFT);$status=$i===34?'CANCELLED':($i===33?'REQUESTED':'CONFIRMED');$payment=$i<=28?'PAID':'UNPAID';$date=$i<=30?'2026-11-14':'2026-11-15';$created=$i===1?'2026-11-13 16:59:59':'2026-11-13 17:00:00';$snapshot=['productName'=>'Trải nghiệm '.$i,'variantName'=>'Vé','date'=>$date,'lines'=>[['quantity'=>2],['quantity'=>1]]];$insert->execute([$id,'JM'.str_pad((string)$i,10,'0',STR_PAD_LEFT),$id,str_repeat('a',64),str_repeat('b',64),json_encode($snapshot),json_encode(['name'=>'Khách '.$i,'email'=>'private@example.test']),$status,$payment,'',$created]);if($i===1)$db->prepare("INSERT INTO jingo_order_tickets(id,order_id,code,code_hash,kind,covers,note) VALUES (?,?,?,?,'TOUR_VOUCHER',3,'')")->execute([$id,$id,'FILE-'.$id,hash('sha256',$id)]);if($status!=='CANCELLED'){$expected[$date==='2026-11-14'?'today':'tomorrow']++;if($i<=28&&$i!==1)$expected['due']++;if($payment==='UNPAID')$expected['unpaid']++;if($status==='REQUESTED')$expected['requested']++;if($i!==1)$expected['created']++;}}
 $result=$service->get(['queue'=>'TODAY','page'=>'999'],$now);overviewCheck($result['counts']===$expected&&$result['page']===2&&count($result['data'])===5,'Counts/pagination');overviewCheck(!isset($result['data'][0]['email'])&&!isset($result['data'][0]['access_hash']),'Overview privacy');$due=$service->get(['queue'=>'DUE'],$now);overviewCheck($due['total']===27&&$due['data'][0]['issued']===0&&$due['data'][0]['guests']===3,'Due queue excludes complete tickets');overviewCheck($service->get(['queue'=>'REQUESTED'],$now)['total']===1,'Requested queue');overviewCheck($service->get(['queue'=>'UNPAID'],$now)['total']===5,'Unpaid queue excludes cancelled');foreach([['page'=>'0'],['queue'=>'bad'],['unknown'=>'x']] as $bad){try{$service->get($bad,$now);throw new RuntimeException('Accepted invalid filter');}catch(HttpError $e){overviewCheck($e->status===400,'Invalid filter status');}}
 $firstId='00000000-0000-4000-8000-000000000002';$db->prepare("INSERT INTO jingo_order_archives(order_id,archived_by,reason) VALUES (?,'admin','Archived fixture')")->execute([$firstId]);overviewCheck($service->get(['queue'=>'DUE'],$now)['total']===26,'Archived order included');
 echo "PASS: overview Vietnam midnight/date ranges, empty results, active-order counts, ticket coverage, queues, pagination/clamping, private projection and strict filters.\n";
}finally{$db=null;$server->exec("DROP DATABASE `$name`");}
